#!/bin/bash
# Task 150-w10-annotate -- meshsim sim/ WORKER10 (branch sim-w10; kit: after 352c25b). TIMING TASK: keep the box quiet while it runs.
# Where the framework's run loop spends its time on the boot (W10): perf record (cycles) on W9's chip, one thread,
# the sort's boot (9 machines), built clang release with -g; perf annotate of run_form for TileCore, Router, Director,
# deliver_link<3>, near_slot, after_far: lines at 0.5% or more. One revision (352c25b). ~2 min.
# From an embedded kit (sim/ at each revision named above). Writes only results/150-w10-annotate/. Scratch in /tmp, removed first
# and at the end. Safe to re-run.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/150-w10-annotate; mkdir -p "$RES"; rm -f "$RES/raw.txt"
W=/tmp/w10-150-w10-annotate; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "b717f746eb9115d5c9e38031d6f17af04491bc1942190bce124172fd5168f08b" ] || { echo "kit sha256 mismatch (want b717f746eb9115d5c9e38031d6f17af04491bc1942190bce124172fd5168f08b)"; exit 2; }
mkdir -p "$W/kit" && tar -xzf "$W/kit.tgz" -C "$W/kit" || exit 2
KITS="after"
FAILS=0; FAIL=0
sec() { echo; echo "==== $*  [$(date +%T)]"; }
verdict() { echo "VERDICT $1: $2"; [ "$2" = PASS ] || FAIL=1; }
START=$(date +%s)
{
sec "machine (D21)"; . "$W/kit/after/sim/tools/machine.sh" "${QUEST_P_CPUS:-}" "${QUEST_E_CPUS:-}"; machine_record "$RES/machine.txt"; uptime
echo "kit: after 352c25b"
# Shared by W10's task bodies. run TAG CPUSET cmd...: one run under taskset (and perf stat when PERF=1: cycles,
# instructions, L1d load misses, LLC load misses, summed per core type); appends "TAG <bench line> [perf: ...]" to
# $RES/raw.txt. field NAME: a key=value field of stdin's lines.
run() {
  local tag=$1 cpus=$2; shift 2
  command -v perf > /dev/null || PERF=0
  if [ "${PERF:-0}" = 1 ]; then
    taskset -c "$cpus" perf stat -x, -e cycles,instructions,L1-dcache-load-misses,LLC-load-misses -o "$W/perf.csv" -- "$@" \
      > "$W/out.txt" 2> "$W/err.txt"
  else
    taskset -c "$cpus" "$@" > "$W/out.txt" 2> "$W/err.txt"
  fi
  local rc=$?
  local line; line=$(grep -E '^(threads|chip) ' "$W/out.txt" | tail -1)
  if [ $rc -ne 0 ] || [ -z "$line" ]; then echo "RUNFAIL $tag rc=$rc: $*"; head -5 "$W/err.txt"; FAILS=$((FAILS + 1)); return 1; fi
  local pc=""
  [ "${PERF:-0}" = 1 ] && pc=" perf: $(awk -F, '$1 ~ /^[0-9]+$/ { n=split($3,a,"/"); ev=(n>1)?a[2]:a[1]; k=(a[1]=="cpu_atom")?"atom":"core";
      v[k "_" ev]+=$1 } END { for (x in v) printf "%s=%s ", x, v[x] }' "$W/perf.csv")"
  echo "$tag $line$pc" | tee -a "$RES/raw.txt"
}
field() { grep -o "$1=[^ ]*" | cut -d= -f2; }
# med TAG FIELD: the median of FIELD over raw.txt's lines starting "TAG "
med() { grep "^$1 " "$RES/raw.txt" | field "$2" | sort -g | awk '{ a[NR]=$1 } END { if (NR) print a[int((NR+1)/2)]; else print "-" }'; }
# Task body (WORKER10): where the time inside the framework's run loop goes on the boot (one thread): perf record
# (cycles) on bench_chip --prog sort --reps 9 built with -g (release flags otherwise), perf annotate of the run loop's
# instantiations for TileCore, Router and Director, and of deliver_link<3> and near_slot: the hot lines.
sec "build (clang release + -g, its own directory)"
for k in $KITS; do
  ( cd "$W/kit/$k/sim" && make -j8 CC_NAME=clang MODE=release B=build/prof RELEASE="-O2 -DNDEBUG -g" build/prof/bench_chip > "$RES/build-$k.log" 2>&1 ) \
    || { tail -20 "$RES/build-$k.log"; verdict "build $k" FAIL; exit 1; }
done
P1=$(take 1 "$P_ONE")
for k in $KITS; do
  cd "$W/kit/$k/sim"
  taskset -c "$P1" perf record -q -e cycles -o "$W/p.data" -- ./build/prof/bench_chip --prog sort --reps 9 > "$RES/run-$k.txt" 2>&1 || { echo "perf record failed"; continue; }
  perf report -i "$W/p.data" --stdio --no-children --percent-limit 0.5 --sort symbol 2>/dev/null | grep -v '^#' | grep -v '^$' | head -40 > "$RES/report-$k.txt"
  cat "$RES/report-$k.txt"
  perf annotate -i "$W/p.data" --stdio -l 2>/dev/null > "$W/ann.txt"
  for sym in 'run_form<units::TileCore' 'run_form<units::Router' 'run_form<units::Director' 'deliver_link<3u>' 'Engine::near_slot' 'Engine::after_far'; do
    echo "==== $sym (lines at 0.5% or more of the symbol)"
    awk -v s="$sym" 'index($0, "Percent |") && index($0, s) { on = 1; print; next } index($0, "Percent |") { on = 0 } on && $1 ~ /^[0-9.]+$/ && $1 + 0 >= 0.5' "$W/ann.txt" | head -60
  done | tee "$RES/annotate-$k.txt"
  cd - > /dev/null
done
verdict "annotate done" PASS
sec "done in $(($(date +%s) - START)) s"
} 2>&1 | tee "$RES/run.log"
grep '^VERDICT' "$RES/run.log" > "$RES/VERDICTS.txt"
rm -rf "$W"
grep -q ': FAIL$' "$RES/VERDICTS.txt" && exit 1
exit 0
